/*
 * A191120  Increasing sequence generated by these rules: a(1)=1, and if x is
 *          in a then 3x-1 and 4x-2 are in a.
 * https://oeis.org/A191120
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn
 * Formula:   a(n) generated by a(1)=1; if x∈a then 3x‑1∈a and 4x‑2∈a
 * Range:     u8 n <= 17, u16 n <= 576, u32 n <= 10000, u64 n <= 10000,
 *            u128 n <= 10000, big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/* The algorithm generates the sequence in increasing order using a
   min‑heap for frontier nodes and an open‑addressing hash set to avoid
   duplicates.  The sequence is generated lazily up to the requested
   index, and memoised for future calls. */

#include <stdbool.h>
#include <stdlib.h>
#include <string.h>

/* ------------------------------------------------------------ */
/*  Helper: hash set for seq_t values                              */
/* ------------------------------------------------------------ */

typedef struct {
    size_t cap;          /* table size (power of two)             */
    size_t len;          /* number of elements stored             */
    seq_t *table;        /* array of table elements, 0 = empty    */
} VisitedSet;

static inline uint64_t hash_seq(seq_t v) {
    return (uint64_t)v;                /* lower 64 bits are enough for hashing   */
}

static void visited_init(VisitedSet *s, size_t cap) {
    /* cap must be power of two */
    size_t c = 1;
    while (c < cap) c <<= 1;
    s->cap = c;
    s->len = 0;
    s->table = (seq_t *)malloc(sizeof(seq_t) * s->cap);
    if (!s->table) abort();
    memset(s->table, 0, sizeof(seq_t) * s->cap);
}

static void visited_free(VisitedSet *s) {
    free(s->table);
    s->table = NULL;
    s->cap = s->len = 0;
}

static void visited_rehash(VisitedSet *s, size_t new_cap) {
    size_t cap = 1;
    while (cap < new_cap) cap <<= 1;
    seq_t *new_table = (seq_t *)malloc(sizeof(seq_t) * cap);
    if (!new_table) abort();
    memset(new_table, 0, sizeof(seq_t) * cap);
    /* re‑insert existing items */
    for (size_t i = 0; i < s->cap; ++i) {
        seq_t v = s->table[i];
        if (v != 0) {
            size_t h = hash_seq(v) & (cap - 1);
            while (new_table[h]) h = (h + 1) & (cap - 1);
            new_table[h] = v;
        }
    }
    free(s->table);
    s->table = new_table;
    s->cap = cap;
}

static bool visited_insert(VisitedSet *s, seq_t v) {
    if (s->len * 8 >= s->cap * 7) /* load > 0.7 */
        visited_rehash(s, s->cap * 2);
    size_t h = hash_seq(v) & (s->cap - 1);
    while (s->table[h]) {
        if (s->table[h] == v) return false;   /* already present */
        h = (h + 1) & (s->cap - 1);
    }
    s->table[h] = v;
    s->len++;
    return true;
}

/* ------------------------------------------------------------ */
/*  Helper: dynamic min‑heap for seq_t values                     */
/* ------------------------------------------------------------ */

typedef struct {
    size_t cap;
    size_t size;
    seq_t *arr;
} MinHeap;

static void heap_init(MinHeap *h, size_t cap) {
    h->cap = cap;
    h->size = 0;
    h->arr = (seq_t *)malloc(sizeof(seq_t) * h->cap);
    if (!h->arr) abort();
}

static void heap_free(MinHeap *h) {
    free(h->arr);
    h->arr = NULL;
    h->cap = h->size = 0;
}

static void heap_grow(MinHeap *h) {
    size_t new_cap = h->cap * 2;
    seq_t *new_arr = (seq_t *)realloc(h->arr, sizeof(seq_t) * new_cap);
    if (!new_arr) abort();
    h->arr = new_arr;
    h->cap = new_cap;
}

static void heap_push(MinHeap *h, seq_t v) {
    if (h->size == h->cap) heap_grow(h);
    size_t idx = h->size++;
    h->arr[idx] = v;
    while (idx > 0) {
        size_t parent = (idx - 1) >> 1;
        if (h->arr[idx] < h->arr[parent]) {
            seq_t tmp = h->arr[idx];
            h->arr[idx] = h->arr[parent];
            h->arr[parent] = tmp;
            idx = parent;
        } else break;
    }
}

static seq_t heap_pop(MinHeap *h) {
    seq_t ret = h->arr[0];
    h->size--;
    if (h->size == 0) return ret;
    h->arr[0] = h->arr[h->size];
    size_t idx = 0;
    while (true) {
        size_t left = (idx << 1) + 1;
        size_t right = left + 1;
        if (left >= h->size) break;
        size_t smallest = left;
        if (right < h->size && h->arr[right] < h->arr[left]) smallest = right;
        if (h->arr[smallest] < h->arr[idx]) {
            seq_t tmp = h->arr[idx];
            h->arr[idx] = h->arr[smallest];
            h->arr[smallest] = tmp;
            idx = smallest;
        } else break;
    }
    return ret;
}

/* ------------------------------------------------------------ */
/*  Main sequence function                                       */
/* ------------------------------------------------------------ */

seq_t a(idx_t n) {
    /* Static state for memoisation */
    static bool init = false;
    static VisitedSet visited;
    static MinHeap frontier;
    static seq_t *cache = NULL;
    static size_t cache_cap = 0;
    static idx_t cache_len = 0;

    if (!init) {
        visited_init(&visited, 32768);
        heap_init(&frontier, 65536);
        /* seed with first term */
        seq_t first = 1;
        visited_insert(&visited, first);
        heap_push(&frontier, first);
        /* prepare cache */
        cache_cap = 64;
        cache = (seq_t *)malloc(sizeof(seq_t) * cache_cap);
        if (!cache) abort();
        cache_len = 0;
        init = true;
    }

    /* generate until we have at least n terms */
    while (cache_len < n) {
        seq_t x = heap_pop(&frontier);
        /* store */
        if (cache_len >= cache_cap) {
            size_t new_cap = cache_cap * 2;
            seq_t *new_cache = (seq_t *)realloc(cache, sizeof(seq_t) * new_cap);
            if (!new_cache) abort();
            cache = new_cache;
            cache_cap = new_cap;
        }
        cache[cache_len++] = x;

        /* generate successors */
        seq_t child1 = 3 * x - 1;
        if (visited_insert(&visited, child1))
            heap_push(&frontier, child1);
        seq_t child2 = 4 * x - 2;
        if (visited_insert(&visited, child2))
            heap_push(&frontier, child2);
    }

    return cache[n - 1];
}
